	if aSweep.ID != lowJob.ID {
		t.Errorf("expected sweep job %s, got %s", lowJob.ID, aSweep.ID)
	}

	// Next general acquire gets batchJob
	a3, err := store.AcquireNext(ctx, 10*time.Second)
	if err != nil || a3 == nil {
		t.Fatalf("failed to acquire 3: %v", err)
	}
